export const categories=['Academics / classes','LeetCode / coding','Internships / jobs','Projects','Personal'];
export const colors=['#9c9ac5','#90ad79','#c6a970','#8fadc0','#bd9391'];
export function day(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
export function dateOf(value){return new Date(value+'T12:00:00')}
export function plus(date,n){const d=dateOf(date);d.setDate(d.getDate()+n);return day(d)}
export function distance(a,b){const [y,m,d]=a.split('-').map(Number),[y2,m2,d2]=b.split('-').map(Number);return Math.round((Date.UTC(y,m-1,d)-Date.UTC(y2,m2-1,d2))/86400000)}
export function monday(today=day()){const d=dateOf(today);return plus(today,-((d.getDay()+6)%7))}
export function validDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)&&day(dateOf(s))===s}
export function relative(d,today=day()){if(!d)return '';const n=distance(d,today);return n===0?'Today':n===1?'Tomorrow':n<0?`${-n}d overdue`:n<7?`In ${n} days`:dateOf(d).toLocaleDateString(undefined,{month:'short',day:'numeric',...(d.slice(0,4)!==today.slice(0,4)?{year:'numeric'}:{})})}
export function createTask(input,now=new Date()){const title=String(input.title??'').trim();if(!title||title.length>300)throw new Error('Add a task name (up to 300 characters).');const due=input.due||'';if(due&&!validDate(due))throw new Error('Choose a valid due date.');const category=categories.includes(input.category)?input.category:'Personal';const repeat=['daily','weekly'].includes(input.repeat)?input.repeat:'none';const importance=Number(input.importance||2);if(![1,2,3].includes(importance))throw new Error('Choose an importance.');const effort=input.effort?Number(input.effort):null;if(effort!==null&&(!Number.isInteger(effort)||effort<1||effort>1440))throw new Error('Use an effort from 1 to 1440 minutes.');return {id:crypto.randomUUID(),title,category,due:due||(repeat!=='none'?day(now):''),repeat,importance,effort,createdAt:now.toISOString(),available:repeat!=='none'?(due||day(now)):'',completedAt:null,deletedAt:null}}
export function active(tasks,today=day()){return tasks.filter(t=>!t.completedAt&&!t.deletedAt)}
export function score(t,today=day()){const d=t.due?distance(t.due,today):999;return (d<0?1000+Math.min(-d,100):d===0?800:d===1?500:d<=3?200:0)+t.importance*30+Math.min(distance(today,day(new Date(t.createdAt))),20)}
export function complete(tasks,id,now=new Date()){const task=tasks.find(t=>t.id===id&&!t.completedAt&&!t.deletedAt);if(!task)throw new Error('That task is no longer open.');if(task.available&&task.available>day(now))throw new Error('This recurring task is scheduled for a later day.');let next=tasks.map(t=>t.id===id?{...t,completedAt:now.toISOString()}:t);if(task.repeat!=='none'){const due=plus(day(now),task.repeat==='daily'?1:7);const child={...task,id:crypto.randomUUID(),parentId:task.id,due,available:due,createdAt:now.toISOString(),completedAt:null};next=[child,...next]}return next}
export function reopen(tasks,id){const target=tasks.find(t=>t.id===id&&t.completedAt&&!t.deletedAt);if(!target)throw new Error('That completion is no longer available.');const child=tasks.find(t=>t.parentId===id&&!t.deletedAt);if(child?.completedAt)throw new Error('A later repeat is already complete. Reopen the most recent occurrence first.');return tasks.filter(t=>t.id!==child?.id).map(t=>t.id===id?{...t,completedAt:null}:t)}
export function weekly(tasks,start,today=day()){const dates=Array.from({length:7},(_,i)=>plus(start,i));const end=dates[6];const done=tasks.filter(t=>!t.deletedAt&&t.completedAt&&day(new Date(t.completedAt))>=start&&day(new Date(t.completedAt))<=end);const days=dates.map(date=>({date,count:done.filter(t=>day(new Date(t.completedAt))===date).length,added:tasks.filter(t=>day(new Date(t.createdAt))===date&&!t.parentId).length,backlog:date>today?null:tasks.filter(t=>day(new Date(t.createdAt))<=date&&(!t.available||t.available<=date)&&(!t.completedAt||day(new Date(t.completedAt))>date)&&(!t.deletedAt||day(new Date(t.deletedAt))>date)).length}));const cutoff=end<today?end:today;const unfinished=tasks.filter(t=>day(new Date(t.createdAt))<=cutoff&&(!t.available||t.available<=cutoff)&&(!t.completedAt||day(new Date(t.completedAt))>cutoff)&&(!t.deletedAt||day(new Date(t.deletedAt))>cutoff));return {days,done,unfinished,overdue:unfinished.filter(t=>t.due&&t.due<cutoff),minutes:done.reduce((n,t)=>n+(t.effort||0),0),cutoff}}
